#!/usr/bin/env python3
"""Persist findings of the bounded substantive review and verify its exact scope."""
from pathlib import Path
from datetime import datetime,timezone
import hashlib,json,re,sys,xml.etree.ElementTree as ET
W=Path(__file__).resolve().parent
D=W/'sources/review-p19-p34'
IDS=['p19','p19a','p19b','p19c','p19d']+['p'+str(i) for i in range(20,35)]
def save(p,x):p.write_text(json.dumps(x,ensure_ascii=False,indent=2)+'\n')
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def sht(t):return hashlib.sha256(t.encode()).hexdigest()
def blocks(s):return {m[1]:m[2].strip() for m in re.finditer(r'^=== (\S+)\s*\n(.*?)(?=^=== |\Z)',s,re.S|re.M)}
NOTES={
'p19':('corrected','Alle zehn Absätze gelesen. Drittauskunftsalternativen, gewerbliches Ausmaß der Drittätigkeit, Umfang nach Abs. 3, Aufwand, Aussetzung, Haftung, Straf-/Bußgeldverwertung und Verkehrsdatenverfahren präzisiert. BGH I ZR 51/12 vollständig gelesen; Kontostammdatenfall und Bankgeheimnis begrenzt eingeordnet.'),
'p19a':('corrected','Alle fünf Absätze geprüft. Wahrscheinlichkeit, Erforderlichkeit, Verfügungsgewalt, zusätzliche Schwelle für Finanzunterlagen und Vertraulichkeit getrennt; § 811 BGB tatsächlich nachgelesen. Fehlende Verletzung und drohende Verletzung sowie gesetzlich nicht genanntes Verschulden bei Abs. 5 erläutert.'),
'p19b':('corrected','Vier Absätze und sämtliche Schadensersatzverweisungen geprüft. Zugang als Alternative zur Vorlage, gefährdete Erfüllung gegenüber Anspruchsbegründung, Verhältnismäßigkeit und Offensichtlichkeit im Eilverfahren erklärt. § 811 BGB konkretisiert; keine Verweisung auf § 19a Abs. 5 behauptet.'),
'p19c':('retained','Siegende Partei einschließlich erfolgreichem Beklagten, berechtigtes Interesse, gerichtliche Begrenzung von Art/Umfang, Kosten, Erlöschen drei Monate nach Rechtskraft und fehlende vorläufige Vollstreckbarkeit geprüft. Fiktives Rehabilitationsbeispiel bleibt zutreffend.'),
'p19d':('retained','Offenhaltung anderer gesetzlicher Ansprüche gegen Wortlaut und § 2 abgeglichen; keine eigene Herausgabegrundlage oder doppelte Kompensation behauptet. Fiktives Beispiel und Durchsetzungscheckliste bleiben sachgerecht.'),
'p20':('corrected','Beide Sätze und Reichweite §§ 14–19c geprüft. BGB §§ 195, 199 und 852 in amtlicher HTML/XML tatsächlich gelesen; regelmäßige Dreijahresfrist, Jahresendbeginn, Unterlassungsanknüpfung, Höchstfristen und begrenzte Restherausgabe konkretisiert. Keine pauschale Fortgeltung aller verjährten Schadensposten.'),
'p21':('corrected','Alle vier Absätze geprüft: fünf aufeinanderfolgende Jahre, Kenntnis, eingetragener Warenumfang, verschiedene Bösgläubigkeitszeitpunkte, beidseitige Koexistenz und allgemeine Verwirkung. In Abs. 2 bislang nicht ausdrücklich erläuterte notorisch bekannte Marken nach § 4 Nr. 3 ergänzt.'),
'p22':('corrected','Beide Absätze und drei Alternativen sowie § 51 Abs. 3/4 gelesen. Unzutreffende zusätzliche Bestandskraftvorstellung entfernt: hypothetisch zurückzuweisender Antrag genügt. Stichtag, historisch fehlende Bekanntheit/Verwechslungsgefahr, Verfall/absolute Hindernisse und Gegenrecht des Älteren getrennt. Fassung seit 16.01.2026 nach Art. 5 Nr. 7 geprüft.'),
'p23':('retained','Alle drei Schranken und Abs. 2 abgeglichen: Eigenname nur natürliche Person, unterscheidungskraftlose oder beschreibende Zeichen sowie Identifizierung/Verweisung. Werkstattbeispiel prüft konkrete Präsentation und wirtschaftliche Verbindung; keine pauschale Logoschranke oder Ausnahme für wahre Angaben.'),
'p24':('retained','Warenbezogene Zustimmung, Inverkehrbringen im Inland/EU/EWR, keine weltweite Erschöpfung und berechtigte Gründe aus Abs. 2 geprüft. Import- und Umpackbeispiele bleiben offen auf erforderliche Prüfung gerichtet, keine automatische globale Freigabe.'),
'p25':('corrected','Beide Absätze einschließlich Einrede, Nachweis, berechtigter Nichtbenutzungsgründe, Ablauf während des Prozesses und Warenbegrenzung geprüft. Unnötige Beschränkung auf ältere Marken entfernt. Taschen-/Bekleidungsbeispiel trennt Nachweisumfang von einer anschließend möglichen Warenähnlichkeit und Kollisionsprüfung.'),
'p26':('corrected','Alle fünf Absätze geprüft: ernsthafte Inlandsbenutzung, Zustimmung, unveränderter kennzeichnender Charakter, Exportbenutzung und Widerspruchsabschluss. Aufmachung/Verpackung in Abs. 4 ergänzt; Abs. 5 mit 2026-Wortlaut und tatsächlicher Änderung Art. 5 Nr. 8 abgeglichen, keine Gleichsetzung der jeweiligen Verfahrenszeiträume.'),
'p27':('corrected','Alle vier Absätze und § 46 gelesen. Entstehungswege, Teilübertragung, betriebliche Zweifelsregel auch beim Verpflichtungsgeschäft und Umschreibungsnachweis geprüft. Exakte Verweisungsausnahmen ergänzt: § 46 Abs. 2 und Abs. 3 Satz 1, nicht die Unwiderruflichkeit aus Satz 2.'),
'p28':('retained','Drei Absätze geprüft. Widerlegliche Registervermutung, Eingang des Umschreibungsantrags statt vollzogener Eintragung als Verfahrensschwelle, bezeichnete Amts-/Rechtsmittelverfahren, zustimmungsfreie Übernahme und zusätzliche Zustellung an Nachfolger korrekt unterschieden.'),
'p29':('retained','Alle drei Absätze und beide Nummern geprüft. Dingliches Recht/Vollstreckung bei allen Markenentstehungswegen, Nachweis und Registerantrag bei Registermarken sowie Insolvenzvermerk und Sachwalter in Eigenverwaltung zutreffend erklärt. Keine registerbedingte Wirksamkeits- oder Ranggarantie behauptet.'),
'p30':('corrected','Alle sechs Absätze und fünf lizenzvertraglichen Tatbestände gelesen. Einfache/ausschließliche, sachliche/räumliche Lizenz, Klagezustimmung und Ausnahme, Beitritt und ältere Lizenzen geprüft. Differenzierte Registerzustimmung bei Eintragung/Änderung/Löschung konkretisiert; Registerlöschung nicht automatisch Vertragsende.'),
'p31':('corrected','Entsprechende Anwendung aller §§ 27–30 auf Anmeldung, Eintragungsrisiko und Erwerbsgegenstand geprüft. Beispiel präzisiert: vor Eintragung besteht aus der Anmeldung kein Registermarkenverletzungsanspruch, nicht bloß kein unangefochtener Anspruch. Checkliste bleibt erhalten.'),
'p32':('retained','Vier Absätze einschließlich Wegfall des Abs. 4 und vier Mindestangaben geprüft. Empfangsstelle, § 8 Abs. 1, weitere Anforderungen nach § 65 und fehlendes Warenverzeichnis mit §§ 33/36/39 abgeglichen; keine freie Erweiterung unter altem Rang angenommen.'),
'p33':('corrected','Drei Absätze gelesen. Vollständiger Eingang, bestimmtes Patentinformationszentrum, gebundene Eintragung und Veröffentlichung samt Identifizierung geprüft. Begrenzte Amtsprüfung nach § 37 Abs. 4/§ 10 ausdrücklich ergänzt; Aktenzeichen ersetzt nicht Nachweis des vollständigen Eingangs.'),
'p34':('corrected','Drei Absätze geprüft: Vertragsgrundlage, Dienstleistungen, bekanntgemachte Gegenseitigkeit, zwei verschiedene Zweimonatsfristen und Verlust der Priorität. Änderungsmöglichkeit innerhalb der jeweiligen Fristen ergänzt und Trennung von materieller Prioritätsfrist und Nachweisfristen gewahrt.')}
baseline=json.loads((D/'commentary-baseline.json').read_text());before=baseline['commentary'];current={}
for p in sorted((W/'commentary').glob('*.md')):current.update(blocks(p.read_text()))
assert set(current)==set(before) and set(IDS)==set(NOTES) and len(IDS)==20
changed=[i for i in current if current[i]!=before[i]]
assert len(changed)==13 and set(changed)<=set(IDS)
for i in IDS:assert (i in changed)==(NOTES[i][0]=='corrected')
u={x['id']:x for x in map(json.loads,(W/'units.jsonl').read_text().splitlines())};root=ET.parse(W/'sources/markeng.xml').getroot();ns={n.attrib['doknr']:n for n in root.findall('norm')}
compact=lambda s:re.sub(r'\s+','',s)
findings=[]
for i in IDS:
 x=u[i];n=ns[x['xml_doknr']];assert compact(x['text'])==compact(''.join(n.find('textdaten/text/Content').itertext()))
 findings.append(dict(id=i,label=x['label'],outcome=NOTES[i][0],finding=NOTES[i][1],resolved=True,source_xml_doknr=x['xml_doknr'],statutory_text_sha256=sht(x['text']),commentary_before_sha256=sht(before[i]),commentary_after_sha256=sht(current[i])))
c=ET.parse(D/'davidoff.xml').getroot();local=compact((D/'davidoff-local.md').read_text());count=0
for tag in ['tenor','tatbestand','entscheidungsgruende']:
 for e in c.findall('.//'+tag+'//p'):
  t=''.join(e.itertext()).strip()
  if t:assert compact(t) in local;count+=1
case=dict(court='BGH',date=c.findtext('entsch-datum'),docket='I ZR 51/12',ecli=c.findtext('ecli'),read_full_text=True,read_scope='Tenor und Rn. 1–37',supported_reviewed_ids=['p19'],official_xml='sources/review-p19-p34/davidoff.xml',official_xml_sha256=sha(D/'davidoff.xml'),corpus_path='sources/review-p19-p34/davidoff-local.md',nonempty_official_paragraphs_compared=count,missing_from_read_corpus=0,card='cases/bgh-davidoff.md',superseded_law_check='Current § 19(2) Nr. 3 and refusal proviso compared. Historical GMV, § 125b and § 143a not asserted as current provisions.')
quality=json.loads((W/'quality-report.json').read_text());coverage=json.loads((W/'completeness-independent.json').read_text())
assert coverage['ok'] and not quality['broken_local_links'] and not quality['exact_repeated_paragraphs'] and not quality['placeholder_matches']
prior=json.loads((D/'prior-review-result.json').read_text());assert prior['complete'] and len(prior['reviewed_ids'])==20 and not set(prior['reviewed_ids'])&set(IDS)
limitations=['Complete refers only to these exact 20 assigned units; no whole-book completion. Previous 20-unit review preserved, 151 units still await second pass.', 'Selective additional case research: one relevant BGH judgment read in full; no exhaustive survey, no added verified decision for the other 19 units, no claim that none exists.', 'Earlier case cards retained without renewed substantive review in this batch. Decisions quoted inside Davidoff are not independently verified authorities here.', 'No complete reconstruction of historical law or every cross-referenced act. Four BGB provisions checked against official current HTML/XML and latest amending article; not a full BGB review.', 'Current MarkenG consolidation and both 2026 amending/commencement texts checked; selective later-law search is not an exhaustive BGBl pipeline audit.', 'Technical coverage, length and repetition checks do not establish legal errorlessness or external professional approval.']
now=datetime.now(timezone.utc).isoformat();technical=None
if '--validated' in sys.argv:
 technical=json.loads((W/'validation.json').read_text());assert technical['ok'] and technical['verbatim_ratio']==1.0
result=dict(complete=True,task='bounded_independent_second_pass',units_reviewed=20,reviewed_ids=IDS,decisive_date='2026-10-19',reviewed_at=now,unresolved_blockers=[],findings=findings,limitations=limitations,changed_ids=changed,retained_ids=[i for i in IDS if i not in changed],whole_book_complete=False,work_baseline_commit=baseline['work_baseline_commit'],baseline_evidence='sources/review-p19-p34/commentary-baseline.json',baseline_evidence_sha256=sha(D/'commentary-baseline.json'),unchanged_unassigned_units=171,unassigned_commentary_unchanged=True,prior_review_result='sources/review-p19-p34/prior-review-result.json',cumulative_reviewed_units=40,remaining_second_pass_units=151,case_checks=[case],source_preflight='preflight-result.json',source_verification='sources/verification.json',technical_validation=technical,technical_validation_pending=technical is None,completeness=dict(expected=coverage['expected_count'],parsed=coverage['parsed_count'],missing=coverage['missing'],extra=coverage['unexpected'],xml_character_mismatch=coverage['xml_character_mismatch']),quality=dict(broken_links=quality['broken_local_links'],repeated_long_sentences=quality['repeated_long_sentences'],placeholder_matches=quality['placeholder_matches']))
save(W/'review-result.json',result)
status=json.loads((W/'status.json').read_text());status.update(stage='bounded_second_pass_complete',task_scope='Exactly p19–p34 including p19a–p19d; no whole-book completion.',reviewed_ids=IDS,units_reviewed=20,review_result='review-result.json',review_completed_at=now,whole_book_review_complete=False,independent_second_pass='Current assigned 20 complete; 40 cumulatively reviewed, 151 pending',updated_at=now,remaining_limitations=limitations,unresolved_blockers=[],cumulative_reviewed_ids=prior['reviewed_ids']+IDS,cumulative_reviewed_units=40,remaining_second_pass_units=151)
status['source_checks']['latest_verification']=json.loads((W/'sources/verification.json').read_text())['last_verified_at'];status['commentary_characters']=sum(map(len,current.values()));status['case_law_sources']=[x for x in status['case_law_sources'] if x['docket']!='I ZR 51/12']+[dict(court='BGH',date='2015-10-21',docket='I ZR 51/12',card='cases/bgh-davidoff.md',read_full_text=True)]
status['case_law_provenance']='Davidoff Hot Water II fully read and fresh official XML verified for current batch; other three case cards retained without new substantive review.'
status['quality_checks'].update(output_local_links=quality['checked_output_links'],broken_links=quality['broken_local_links'],repeated_paragraphs=quality['exact_repeated_paragraphs'],repeated_long_sentences=quality['repeated_long_sentences'],other_commentary_blocks='All 171 unassigned commentary blocks unchanged against baseline '+baseline['work_baseline_commit'],unchanged_commentary_units=178,retained_reviewed_units=7,corrected_reviewed_units=13)
if technical is not None:status['validation_result']=technical
save(W/'status.json',status)
log=json.loads((W/'sources/search-log.json').read_text());log['bounded_review_p19_p34']=dict(checked_at=now,queries=[dict(query='site:recht.bund.de Markengesetz Änderung 2026 Oktober September',evidence='sources/review-p19-p34-amendments-search.json',result='Three results: latest and preceding MarkenG amendments plus previously checked DPMA regulation; no evidenced later MarkenG amendment'),dict(query='site:rechtsprechung-im-internet.de "Davidoff Hot Water"',result='No search results; CLI did not create output file'),dict(query='BGH I ZR 51/12 Davidoff Hot Water 21.10.2015',evidence='sources/review-p19-p34-cases-search.json',result='Search used only for discovery, official BGH press release and third-party links; actual authority verified separately through local RII corpus and official XML ZIP')],local_corpus_query='rg exact case_number and BGH title I ZR 51/12; selected final judgment KORE303312016 rather than referral KORE306452013',fresh_fetches='sources/review-p19-p34/fetches.json',case_checks=[case],no_new_case_selected_ids=[i for i in IDS if i!='p19'],limit=limitations[1]);save(W/'sources/search-log.json',log)
manifest=dict(created_at=now,primary_statute='markeng.xml',canonical_statute='canonical.md',files=[dict(path=str(p.relative_to(W)),bytes=p.stat().st_size,sha256=sha(p)) for p in sorted((W/'sources').rglob('*')) if p.is_file() and p.name!='manifest.json']);save(W/'sources/manifest.json',manifest)
print(json.dumps(dict(complete=True,units_reviewed=20,corrected=len(changed),retained=7,unassigned_unchanged=171,whole_book_complete=False,technical_validation_pending=technical is None)))
